  from src, tp
  where c.topic_id = tp.id and c.metadata ->> 'source' = 'spring_boot_seed' and c.metadata ->> 'block' = 'practice'
    and (c.heading, c.body, c.content_format, c.sort_order) is distinct from ($sb134$Practice Problems$sb134$, src.body, 'markdown', 1)
  returning c.id
)
