do $val$
declare
  v_topics int; v_lessons int; v_practice int; v_tests int; v_questions int; v_web boolean; v_mob boolean;
begin
  select count(*) into v_topics from public.learning_topics where source_kind = 'spring_boot_tutorial' and source_ref in ($sb155$getting-started/spring-vs-spring-boot$sb155$, $sb156$getting-started/installing-jdk-and-ide-for-spring-boot$sb156$, $sb157$getting-started/creating-a-project-with-spring-initializr$sb157$, $sb158$getting-started/spring-boot-project-structure$sb158$, $sb159$getting-started/maven-pom-xml-explained$sb159$);
  if v_topics <> 5 then raise exception 'validation: expected 5 topics, found %', v_topics; end if;
  select count(*) filter (where c.metadata ->> 'block' = 'lesson'), count(*) filter (where c.metadata ->> 'block' = 'practice')
    into v_lessons, v_practice
    from public.learning_contents c join public.learning_topics t on t.id = c.topic_id
   where c.metadata ->> 'source' = 'spring_boot_seed' and t.source_kind = 'spring_boot_tutorial' and t.source_ref in ($sb155$getting-started/spring-vs-spring-boot$sb155$, $sb156$getting-started/installing-jdk-and-ide-for-spring-boot$sb156$, $sb157$getting-started/creating-a-project-with-spring-initializr$sb157$, $sb158$getting-started/spring-boot-project-structure$sb158$, $sb159$getting-started/maven-pom-xml-explained$sb159$);
  if v_lessons <> 5 then raise exception 'validation: expected 5 lesson blocks, found %', v_lessons; end if;
  if v_practice <> 3 then raise exception 'validation: expected 3 practice blocks, found %', v_practice; end if;
  select count(*) into v_tests from public.practice_tests where id in ('pt-sb-spring-vs-spring-boot', 'pt-sb-installing-jdk-and-ide-for-spring-boot', 'pt-sb-creating-a-project-with-spring-initializr', 'pt-sb-spring-boot-project-structure', 'pt-sb-maven-pom-xml-explained') and learning_topic_id is not null;
  if v_tests <> 5 then raise exception 'validation: expected 5 linked mock tests, found %', v_tests; end if;
  select count(*) into v_questions from public.test_questions where test_id in ('pt-sb-spring-vs-spring-boot', 'pt-sb-installing-jdk-and-ide-for-spring-boot', 'pt-sb-creating-a-project-with-spring-initializr', 'pt-sb-spring-boot-project-structure', 'pt-sb-maven-pom-xml-explained');
  if v_questions <> 25 then raise exception 'validation: expected 25 MCQs, found %', v_questions; end if;
  select show_on_website, show_on_mobile into v_web, v_mob from (select id, show_on_website, show_on_mobile from public.learning_grids where lower(slug) = 'spring-boot-tutorial' and source_kind = 'seed' and source_ref = 'spring_boot_tutorial') g;
  raise notice '0131/102 OK: Spring Boot Tutorial batch 02: % topics, % lesson blocks, % practice blocks, % tests, % MCQs. Grid visible on website=%, mobile=%.',
    v_topics, v_lessons, v_practice, v_tests, v_questions, v_web, v_mob;
end
$val$;

